import random

GROUP = "number_theory"
SKILL = "induction"


def find_max_integer_sum(n, min_divisor, max_divisor):
    if n == 0:
        return 0

    if n < min_divisor:
        return -1

    max_sum = 0

    for d in range(min_divisor, max_divisor + 1):
        if d <= n:
            remaining_sum = n - d
            count = find_max_integer_sum(remaining_sum, min_divisor, d - 1)

            if count != -1:
                max_sum = max(max_sum, count + 1)

    return max_sum


def generate(seed):
    rng = random.Random(seed)

    min_divisor = rng.randint(3, 7)
    max_divisor = rng.randint(7, 15)
    n = rng.randint(100, 1000)

    answer = find_max_integer_sum(n, min_divisor, max_divisor)

    check = -1
    for d in range(min_divisor, max_divisor + 1):
        if d <= n:
            remaining_sum = n - d
            count = find_max_integer_sum(remaining_sum, min_divisor, d - 1)
            if count != -1:
                check = max(check, 1 + count)

    assert answer == check, f"answer={answer} check={check}"

    problem = (
        f"Consider integers divisible by divisors from {min_divisor} to {max_divisor} (inclusive). "
        f"What is the maximum number of distinct integers that can be selected such that no integer exceeds the total sum {n} and the sum of their divisors is exactly {n}? State only the integer."
    )
    return problem, str(answer)
